#!/usr/bin/env node
/**
 * Generates the component API reference modules consumed by the docs app:
 *   projects/docs/src/app/generated/component-api/<family>.generated.ts
 *   projects/docs/src/app/generated/component-api.registry.generated.ts
 *
 * Input is docs/quality/inventory.json (regenerated by tools/quality/inventory.mjs).
 * One module per family keeps every API table in its own lazy chunk, so the
 * generic documentation page only ships the reference it renders. The output
 * is committed so the docs build needs no prebuild step; drift is caught in
 * CI via --check (part of verify:docs).
 *
 * Usage:
 *   node tools/docs/generate-component-api.mjs          # regenerate
 *   node tools/docs/generate-component-api.mjs --check  # fail on drift
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import prettier from "prettier";
import {
  buildComponentApi,
  renderFamilyModule,
  renderRegistryModule,
} from "./component-api-lib.mjs";

const root = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../..",
);
const inventoryPath = path.join(root, "docs/quality/inventory.json");
const generatedDir = path.join(root, "projects/docs/src/app/generated");
const familiesDir = path.join(generatedDir, "component-api");
const registryPath = path.join(
  generatedDir,
  "component-api.registry.generated.ts",
);

const check = process.argv.includes("--check");

const inventory = JSON.parse(fs.readFileSync(inventoryPath, "utf8"));
const api = buildComponentApi(inventory);
const families = Object.keys(api);

async function format(source, filepath) {
  const config = {
    ...(await prettier.resolveConfig(filepath, { editorconfig: true })),
    filepath,
  };
  return prettier.format(source, config);
}

const entryCount = Object.values(api).reduce(
  (total, members) =>
    total + members.reduce((sum, member) => sum + member.entries.length, 0),
  0,
);

const outputs = new Map();
for (const family of families) {
  const familyPath = path.join(familiesDir, `${family}.generated.ts`);
  outputs.set(
    familyPath,
    await format(renderFamilyModule(family, api[family]), familyPath),
  );
}
outputs.set(
  registryPath,
  await format(renderRegistryModule(families), registryPath),
);

if (check) {
  const stale = [];
  for (const [outputPath, formatted] of outputs) {
    const current = fs.existsSync(outputPath)
      ? fs.readFileSync(outputPath, "utf8")
      : null;
    if (current !== formatted) stale.push(path.relative(root, outputPath));
  }
  const onDisk = fs.existsSync(familiesDir)
    ? fs
        .readdirSync(familiesDir)
        .filter((name) => name.endsWith(".generated.ts"))
        .map((name) => path.join(familiesDir, name))
    : [];
  for (const file of onDisk) {
    if (!outputs.has(file))
      stale.push(`${path.relative(root, file)} is orphaned`);
  }
  if (stale.length) {
    console.error(
      `Stale component API reference files. Run: npm run docs:generate-api`,
    );
    for (const file of stale) console.error(`  ${file}`);
    process.exit(1);
  }
  console.log(
    `component API reference up to date (${families.length} families, ${entryCount} entries).`,
  );
  process.exit(0);
}

fs.mkdirSync(familiesDir, { recursive: true });
for (const [outputPath, formatted] of outputs) {
  fs.writeFileSync(outputPath, formatted);
}
// Families removed from the inventory must not linger as dead chunks.
for (const file of fs.existsSync(familiesDir)
  ? fs
      .readdirSync(familiesDir)
      .filter((name) => name.endsWith(".generated.ts"))
      .map((name) => path.join(familiesDir, name))
  : []) {
  if (!outputs.has(file)) fs.unlinkSync(file);
}
console.log(
  `wrote ${families.length} family modules + registry into ${path.relative(root, familiesDir)} (${entryCount} entries).`,
);
